Ext.define('BNK.view.Budget.bgx.BgxNfmAply31M', {
    extend: 'Ext.Container',
    alias: 'widget.BgxNfmAply31M',

    alternateClassName: [
        'BgxNfmAply31M'
    ],
    requires: [
        'BNK.view.Budget.bgx.BgxNfmAply31MViewModel',
        'BNK.view.Budget.bgx.BgxNfmAply31MViewController',
        'Ext.grid.Grid',
        'Ext.grid.column.Column',
        'Ext.grid.plugin.PagingToolbar'
    ],

    controller: 'BgxNfmAply31MViewController',
    viewModel: {
        type: 'BgxNfmAply31MViewModel'
    },

    items: [
        {
            xtype: 'grid',
            signTpl1: '<span style="font-weight:{text};">{value}</span>',
            signTpl2: '<div style="font-weight:bold;width:100%;overflow: hidden;white-space:nowrap;text-overflow:ellipsis;display:inline-block;">{value1}</div><div>{value2}</div>',
            signTpl3: '<div style="text-align:right;">{value1}</div><div style="text-align:right;color:{color};font-weight:{text};">{value2}</div>',
            signTpl4: '<div style="font-weight:bold;width:100%;overflow: hidden;white-space:nowrap;text-overflow:ellipsis;display:inline-block;">{value1}</div><div>{value2}</div><div style="font-weight:bold;">{value3}</div>',
            signTpl5: '<div style="text-align:right;">{value1}</div><div style="text-align:right;color:{color};font-weight:{text};">{value2}</div><div style="text-align:right;font-weight:{text};">{value3}</div>',
            reference: 'grid',
            height: '100%',
            width: '100%',
            infinite: false,
            variableHeights: true,
            columnResize: false,
            hideHeaders: true,
            bind: {
                store: '{ExpListStore}'
            },
            columns: [
                {
                    xtype: 'gridcolumn',
                    renderer: function(value, record, dataIndex, cell, column) {
                        var me = this,
                            vm = me.getViewModel(),
                            refs = me.getReferences(),
                            value = CodeUtils.getText('NFC001', value),
                            tpl = me.up('grid').lookupTpl('signTpl1'),
                            result = tpl.apply({
                                text : 'bold',
                                value : value
                            });

                        return result;
                    },
                    width: '30%',
                    cell: {
                        xtype: 'gridcell',
                        encodeHtml: false
                    },
                    dataIndex: 'aplKndcd'
                },
                {
                    xtype: 'gridcolumn',
                    renderer: function(value, record, dataIndex, cell, column) {
                        var me = this,
                            vm = me.getViewModel(),
                            refs = me.getReferences(),
                            mcNm = record.data.mcNm,						// 상호
                            aplDt = record.data.aplDt,						// 신청일자
                            trnsDt = record.data.matrnTrnsDt,				// 이체일자
                            trnsStsMsg = record.data.trnsStsMsg,			/* 사용자에게는 정상만 출력되도록 함 .*/
                            tpl = me.up('grid').lookupTpl('signTpl2'),
                            result = tpl.apply({
                                text : 'bold',
                                value1 : mcNm,
                                value2 : DateUtils.parseDate(aplDt)
                            });

                        if (trnsDt != null && trnsStsMsg == '정상') {
                            tpl = me.up('grid').lookupTpl('signTpl4');
                            result = tpl.apply({
                                text : 'bold',
                                value1 : mcNm,
                                value2 : DateUtils.parseDate(aplDt),
                                value3 : '이체일자'
                            });
                        }

                        return result;
                    },
                    width: '35%',
                    cell: {
                        xtype: 'gridcell',
                        encodeHtml: false
                    },
                    dataIndex: 'mcNm'
                },
                {
                    xtype: 'gridcolumn',
                    renderer: function(value, record, dataIndex, cell, column) {
                        var me = this,
                            vm = me.getViewModel(),
                            refs = me.getReferences(),
                            trnsAmt = record.data.trnsAmt,					// 금액
                            aplStcd = record.data.aplStcd,					// 신청상태
                            trnsDt = record.data.matrnTrnsDt,				// 이체일자
                            trnsStsMsg = record.data.trnsStsMsg,			/* 사용자에게는 정상만 출력되도록 함 .*/
                            tpl = me.up('grid').lookupTpl('signTpl3'),
                            aplStcdNm = '',
                            aplStcdStore = me.up('BgxNfmAply01M').getReferences().aplStcd.getStore().data.items,
                            aplDvcd = record.data.aplDvcd,			// 신청구분
                            aplDvcdNm = (aplDvcd == Constants.aplDvcd.APPLY) ? '정상' : '취소';

                        for (var item in aplStcdStore) {
                            var data = aplStcdStore[item].data;
                            if (data && data.value == aplStcd) {
                                aplStcdNm = data.text;
                            }
                        }

                        var result = tpl.apply({
                            text : 'bold',
                            //         color : (aplStcd == Constants.aplStcd.COMPLETED || aplStcd == Constants.aplStcd.COMPLETED_APPLY) ? 'blue' : ((aplStcd == Constants.aplStcd.SEND_BACK || aplStcd == Constants.aplStcd.SEND_BACK_CGP || aplStcd == Constants.aplStcd.SEND_BACK_DEPT) ? 'red' : 'black'),
                            color : (aplDvcd == Constants.aplDvcd.APPLY && aplStcd == Constants.aplStcd.COMPLETED) ? 'blue' : (aplDvcd == Constants.aplDvcd.CANCLE && aplStcd == Constants.aplStcd.COMPLETED) ? 'red' : 'black',
                            value1 : (trnsAmt) ? trnsAmt.toString().replace(/\B(?=(\d{3})+(?!\d))/g,",")+' 원' : trnsAmt ,
                            value2 : '(' + aplDvcdNm + ') ' + aplStcdNm
                        });

                        if (trnsDt != null && trnsStsMsg == '정상') {
                            tpl = me.up('grid').lookupTpl('signTpl5');
                            result = tpl.apply({
                                text : 'bold',
                                color : (aplDvcd == Constants.aplDvcd.APPLY && aplStcd == Constants.aplStcd.COMPLETED) ? 'blue' : (aplDvcd == Constants.aplDvcd.CANCLE && aplStcd == Constants.aplStcd.COMPLETED) ? 'red' : 'black',
                                value1 : (trnsAmt) ? trnsAmt.toString().replace(/\B(?=(\d{3})+(?!\d))/g,",")+' 원' : trnsAmt ,
                                value2 : '(' + aplDvcdNm + ') ' + aplStcdNm,
                                value3 : DateUtils.parseDate(trnsDt)
                            });
                        }

                        return result;
                    },
                    width: '35%',
                    align: 'right',
                    cell: {
                        xtype: 'gridcell',
                        encodeHtml: false
                    },
                    dataIndex: 'aplStcd'
                }
            ],
            plugins: [
                {
                    type: 'gridpagingtoolbar'
                }
            ],
            listeners: {
                select: 'onGridSelect'
            }
        }
    ],
    listeners: {
        initialize: 'initialize'
    }

});